@app.route('/ario-image/<name>')
def ario_image(name):
    payload = ARIO_IMAGE_ASSETS.get(name)
    if not payload:
        abort(404)
    return Response(base64.b64decode(payload), mimetype='image/jpeg', headers={'Cache-Control': 'public, max-age=86400'})

