def save_data(data):
    """Persist site content on disk using an atomic replace to avoid partial files."""
    os.makedirs(BASE_DIR, exist_ok=True)
    fd, temp_path = tempfile.mkstemp(prefix='school_data_', suffix='.tmp', dir=BASE_DIR)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=4)
            f.flush()
            os.fsync(f.fileno())
        # Keep the previous valid data as a recovery copy.
        if os.path.exists(DATA_FILE):
            backup_path = DATA_FILE + '.bak'
            with open(DATA_FILE, 'rb') as src, open(backup_path, 'wb') as dst:
                dst.write(src.read())
                dst.flush()
                os.fsync(dst.fileno())
        os.replace(temp_path, DATA_FILE)
        try:
            if has_request_context() and session.get('username') and '_suite_audit' in globals():
                _suite_audit(session.get('username'), 'ذخیره تغییرات اطلاعات مدرسه', 'school_data.json', 'تغییر اطلاعات اصلی سایت یا مدرسه')
        except Exception:
            pass
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)


@app.before_request
def _sync_authenticated_user_role():
    """Keep active sessions in sync with promoted, demoted, or deleted accounts."""
    username = session.get('username')
    if not username:
        return
    try:
        account = load_data().get('users', {}).get(username)
    except (OSError, ValueError, TypeError):
        account = None
    if not account:
        session.clear()
        return
    session['role'] = account.get('role', 'دانش‌آموز')


