@app.route('/news')
def news_page():
    if 'username' not in session: return redirect(url_for('index'))
    data = load_data()
    items = [item for item in reversed(data['sections'].get('news', [])) if not _is_student_day_news(item)]
    news_cards = []
    for i,item in enumerate(items):
        news_words = (str(item.get('title', '')) + ' ' + str(item.get('text', ''))).lower()
        if any(k in news_words for k in ('ربات', 'فناوری', 'robot', 'technology', 'کدنویسی')):
            image_url = '/ario-image/activity_robotics'
        elif any(k in news_words for k in ('ورزش', 'فوتبال', 'مسابقه', 'sports', 'قهرمان')):
            image_url = '/ario-image/sports'
        elif any(k in news_words for k in ('آزمایش', 'علوم', 'science', 'پژوهش')):
            image_url = '/ario-image/lab'
        elif any(k in news_words for k in ('ساختمان', 'مدرسه', 'افتتاح', 'campus')):
            image_url = '/ario-image/school_about'
        else:
            image_url = '/ario-image/news_event' if i % 2 == 0 else '/ario-image/activity_robotics'
        date_html = f'<span class="news-date">{safe_html(_ario_shamsi_date(item.get("date", "خبر مدرسه")))}</span>'
        news_cards.append(f'<article class="journal-row" data-reveal><div class="journal-photo" style="background-image:url(\'{safe_html(image_url)}\')"></div><div class="journal-copy">{date_html}<h3>{safe_html(localized_value(item, "title", ""))}</h3><p>{safe_html(localized_value(item, "text", ""))}</p></div><span class="journal-arrow"><i class="fas fa-arrow-left"></i></span></article>')
    cards_html = ''.join(news_cards)
    content = f"""<main class="inner-page editorial-inner">
      <section class="inner-hero journal-hero"><div class="inner-hero-image" style="background-image:url('/ario-image/news_event')"></div><div class="inner-hero-overlay"></div><div class="inner-hero-copy"><span class="section-eyebrow">ARIO JOURNAL · LATEST STORIES</span><h1>روایت روزهای<br><em>پر اتفاق آریو.</em></h1><p>خبرها، لحظه‌ها و اتفاق‌هایی که ارزش به خاطر سپردن دارند.</p></div></section>
      <section class="story-layout"><div class="story-side"><span>ARIO JOURNAL</span><h2>خبرهای<br>مدرسه.</h2></div><div class="story-main"><p class="story-lead">هر روز در آریو داستانی تازه برای گفتن وجود دارد.</p><p>اینجا می‌توانید خبرها، رویدادها و لحظه‌های مهم جامعه مدرسه را دنبال کنید.</p></div></section>
      <section class="journal-list">{cards_html or '<div class="empty-state">هنوز خبری منتشر نشده است. به‌زودی اینجا پر از خبرهای تازه می‌شود.</div>'}</section>
    </main>"""
    return render_template_string(BASE_TEMPLATE.replace("{% block content %}{% endblock %}", content).replace("{{ title }}", "اخبار").replace("{{ active_page }}", "news"))

