            ('ابزارهای آموزشی', '/school/teacher-tools', 'fa-toolbox', 'teacher_tools'),
            ('پرونده‌ها', '/school/students', 'fa-id-card', 'students'),
            ('گزارش‌ها', '/school/reports', 'fa-chart-pie', 'reports'),
