# ======================================================================
# ARIO HARDENING PACK — persistent login throttling and safer HTTP headers.
# Additive only: existing school content and school_data.json are preserved.
# ======================================================================
ARIO_LOGIN_MAX_FAILURES = 10
ARIO_LOGIN_WINDOW_SECONDS = 15 * 60
ARIO_LOGIN_LOCK_SECONDS = 10 * 60

def _ario_login_rate_key(username):
    remote = (request.headers.get('X-Forwarded-For', '').split(',')[0].strip()
              or request.remote_addr or 'unknown')
    raw = f'{remote}|{str(username or "").strip().casefold()}'
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()

def _ario_login_rate_db():
    conn = sqlite3.connect(PRESENCE_DB, timeout=8)
    conn.execute('PRAGMA busy_timeout=8000')
    conn.execute('''CREATE TABLE IF NOT EXISTS login_rate_limits (
        rate_key TEXT PRIMARY KEY,
        failures INTEGER NOT NULL DEFAULT 0,
        window_started REAL NOT NULL,
        blocked_until REAL NOT NULL DEFAULT 0
    )''')
    return conn

def _ario_login_attempt_allowed(username):
    key, now = _ario_login_rate_key(username), datetime.now().timestamp()
    conn = _ario_login_rate_db()
    try:
        row = conn.execute('SELECT failures, window_started, blocked_until FROM login_rate_limits WHERE rate_key=?', (key,)).fetchone()
        if not row:
            return True, 0
        failures, started, blocked_until = row
        if blocked_until and blocked_until > now:
            return False, int(blocked_until - now)
        if now - started > ARIO_LOGIN_WINDOW_SECONDS:
            conn.execute('DELETE FROM login_rate_limits WHERE rate_key=?', (key,))
            conn.commit()
        return True, 0
    finally:
        conn.close()

def _ario_login_attempt_failed(username):
    key, now = _ario_login_rate_key(username), datetime.now().timestamp()
    conn = _ario_login_rate_db()
    try:
        row = conn.execute('SELECT failures, window_started FROM login_rate_limits WHERE rate_key=?', (key,)).fetchone()
        if not row or now - row[1] > ARIO_LOGIN_WINDOW_SECONDS:
            failures, started = 1, now
        else:
            failures, started = int(row[0]) + 1, float(row[1])
        blocked_until = now + ARIO_LOGIN_LOCK_SECONDS if failures >= ARIO_LOGIN_MAX_FAILURES else 0
        conn.execute('''INSERT INTO login_rate_limits(rate_key,failures,window_started,blocked_until)
            VALUES(?,?,?,?) ON CONFLICT(rate_key) DO UPDATE SET
            failures=excluded.failures, window_started=excluded.window_started,
            blocked_until=excluded.blocked_until''', (key, failures, started, blocked_until))
        conn.execute('DELETE FROM login_rate_limits WHERE window_started < ?', (now - 2 * 86400,))
        conn.commit()
    finally:
        conn.close()

def _ario_login_attempt_clear(username):
    key = _ario_login_rate_key(username)
    conn = _ario_login_rate_db()
    try:
        conn.execute('DELETE FROM login_rate_limits WHERE rate_key=?', (key,))
        conn.commit()
    finally:
        conn.close()

@app.after_request
def _ario_security_response_headers(response):
    response.headers.setdefault('X-Content-Type-Options', 'nosniff')
    response.headers.setdefault('X-Frame-Options', 'SAMEORIGIN')
    response.headers.setdefault('Referrer-Policy', 'strict-origin-when-cross-origin')
    response.headers.setdefault('Permissions-Policy', 'camera=(), microphone=(), geolocation=(self)')
    if request.is_secure:
        response.headers.setdefault('Strict-Transport-Security', 'max-age=31536000; includeSubDomains')
    if request.path.startswith(('/school', '/parents', '/admin', '/profile', '/api/school')):
        response.headers['Cache-Control'] = 'no-store, private'
        response.headers['Pragma'] = 'no-cache'
    return response

@app.route('/school/security-center')
def ario_suite_security_center():
    context = _suite_current_context(allow_parent=False)
    if not context:
        return redirect(url_for('index'))
    data, portal, username, role, account = context
    if not _suite_is_admin(role):
        abort(403)
    db_checks = []
    for label, path in (
        ('اطلاعات اصلی مدرسه', DATA_FILE),
        ('پایگاه داده حضور آنلاین', PRESENCE_DB),
        ('پایگاه داده پیام‌ها و گزارش‌ها', ARIO_SUITE_DB),
    ):
        exists = os.path.isfile(path)
        size = os.path.getsize(path) if exists else 0
        db_checks.append(f'<tr><td>{_school_html(label)}</td><td>{"آماده" if exists else "ایجاد می‌شود"}</td><td>{_school_html(f"{size:,} بایت" if exists else "—")}</td></tr>')
    try:
        conn = _ario_login_rate_db()
        try:
            now = datetime.now().timestamp()
            active_locks = int(conn.execute('SELECT COUNT(*) FROM login_rate_limits WHERE blocked_until > ?', (now,)).fetchone()[0])
            recent_failures = int(conn.execute('SELECT COALESCE(SUM(failures),0) FROM login_rate_limits WHERE window_started > ?', (now - ARIO_LOGIN_WINDOW_SECONDS,)).fetchone()[0])
        finally:
            conn.close()
        login_status = 'فعال'
    except sqlite3.Error:
        active_locks, recent_failures, login_status = 0, 0, 'نیازمند بررسی'
    content = f'''<main class="ario-school-wrap">
      <section class="ario-school-hero"><span class="ario-school-eyebrow">ARIO SECURITY & OPERATIONS</span>
        <h1>مرکز امنیت و سلامت سامانه</h1>
        <p>نمای کلی از وضعیت فایل‌های اصلی، پایگاه‌های داده و محافظت ورود کاربران.</p>
        <div class="ario-school-actions"><span class="ario-school-chip">محدودسازی تلاش ورود: {_school_html(login_status)}</span>
        <span class="ario-school-chip">حداکثر {ARIO_LOGIN_MAX_FAILURES} تلاش ناموفق</span>
        <span class="ario-school-chip">قفل موقت {ARIO_LOGIN_LOCK_SECONDS // 60} دقیقه‌ای</span></div>
      </section>
      <section class="ario-school-kpis">
        <article class="ario-school-kpi"><strong>{recent_failures}</strong><span>تلاش ناموفق در بازه اخیر</span></article>
        <article class="ario-school-kpi"><strong>{active_locks}</strong><span>محدودیت ورود فعال</span></article>
        <article class="ario-school-kpi"><strong>{len(data.get('users', {}))}</strong><span>حساب ثبت‌شده</span></article>
        <article class="ario-school-kpi"><strong>{len(portal.get('classes', {}))}</strong><span>کلاس تعریف‌شده</span></article>
      </section>
      <section class="ario-school-panel"><h2>سلامت فایل‌ها و پایگاه‌های داده</h2>
        <div class="ario-school-table-wrap"><table class="ario-school-table"><thead><tr><th>بخش</th><th>وضعیت</th><th>حجم</th></tr></thead><tbody>{''.join(db_checks)}</tbody></table></div>
        <p style="color:#f3d39c;line-height:2;font-size:.8rem;margin-top:14px">برای ماندگاری اطلاعات روی هاست، فایل‌های school_data.json، ario_presence.sqlite3، ario_suite.sqlite3 و پوشه ario_backups باید روی فضای ذخیره‌سازی پایدار قرار بگیرند. این صفحه وجود فایل‌ها را بررسی می‌کند، نه سلامت کامل دیسک یا صحت نسخه پشتیبان خارجی را.</p>
      </section>
      <section class="ario-school-panel"><h2>اقدام‌های مدیریتی</h2>
        <div class="ario-school-actions"><a class="ario-school-btn primary" href="/school/backup">مدیریت نسخه‌های پشتیبان</a>
        <a class="ario-school-btn" href="/school/audit">مشاهده گزارش فعالیت‌ها</a>
        <a class="ario-school-btn" href="/school/reports">گزارش‌های تحلیلی</a></div>
      </section></main>'''
    return _suite_page(content, 'مرکز امنیت آریو', 'security')

